'@
$zipPath = Join-Path $PWD "repair-di-store.zip"
$libPath = Join-Path $PWD "mobile\lib"
[IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String(($b64 -replace "\s","")))
Expand-Archive -Path $zipPath -DestinationPath $libPath -Force
Remove-Item $zipPath -Force

# Verify DI restored
$inj = Join-Path $libPath "app\injection.dart"
if (-not (Select-String -Path $inj -Pattern "adminRepository" -Quiet)) { Write-Error "Repair failed: adminRepository missing" }
if (-not (Select-String -Path $inj -Pattern "resellerRepository" -Quiet)) { Write-Error "Repair failed: resellerRepository missing" }
if (-not (Select-String -Path (Join-Path $libPath "presentation\customer\tabs\store_tab.dart") -Pattern "Shop on Digititan Store website" -Quiet)) {
  Write-Error "Repair failed: Store website button missing"
}

Write-Host "SUCCESS: Repair complete"
Write-Host "Verified: adminRepository + resellerRepository + Store website CTA"
Write-Host "Next:"
Write-Host "  cd mobile"
Write-Host "  flutter run -d emulator-5554"
